function poll_(b) {
  const sender = touchSender_(b.device);
  if (!sender) return { ok: false, error: 'جهاز غير معروف' };
  if (sender.status !== 'فعّال') return { ok: true, message: null, paused: true };

  const q = SpreadsheetApp.getActive().getSheetByName(SH.QUEUE);
  const n = q.getLastRow() - 1;
  if (n < 1) return { ok: true, message: null };
  const v = q.getRange(2, 1, n, HEAD.QUEUE.length).getValues();
  const now = new Date();
  const lim = limitsState_(v, now);   // حدود الأمان: الرسائل الزايدة تنتظر (ما تنحذف) لحد ما ينفتح مجال

  for (let i = 0; i < v.length; i++) {
    const r = v[i];
    const mine = !r[Q.SENDER] || r[Q.SENDER] === sender.name;
    if (!mine) continue;
    const stale = r[Q.STATUS] === ST.SENDING && (now - new Date(r[Q.SENT] || r[Q.TIME])) > LOCK_MINUTES * 60000;
    if (r[Q.STATUS] !== ST.PENDING && !stale) continue;
    if (!limitAllows_(lim, r)) continue;

    const row = i + 2;
    q.getRange(row, Q.SENDER + 1).setValue(sender.name);
    q.getRange(row, Q.STATUS + 1).setValue(ST.SENDING);
    q.getRange(row, Q.TRIES + 1).setValue(Number(r[Q.TRIES] || 0) + 1);
    q.getRange(row, Q.SENT + 1).setValue(now);   // وقت السحب (يتحدث عند الإرسال)
    let file = null; try { file = r[Q.FILE] ? JSON.parse(r[Q.FILE]) : null; } catch (e) { file = null; }
    // دمج: رسائل نصية ثانية بالانتظار لنفس الكروب/الرقم تطلع ويا هاي برسالة وحدة (أقل عدد رسائل = أأمن للرقم، وما ينحذف شي)
    let text = String(r[Q.TEXT]);
    if (!file && r[Q.TYPE] !== 'فحص') {
      const merged = [];
      for (let j = i + 1; j < v.length && merged.length < MERGE_MAX; j++) {
        const x = v[j];
        if (x[Q.STATUS] !== ST.PENDING || x[Q.FILE] || x[Q.TYPE] === 'فحص' || String(x[Q.TARGET]) !== String(r[Q.TARGET])) continue;
        if (x[Q.SENDER] && x[Q.SENDER] !== sender.name) continue;
        const t = String(x[Q.TEXT] || ''); if (!t.trim()) continue;
        if (text.length + t.length + MERGE_SEP.length > MERGE_CHARS) break;
        text += MERGE_SEP + t; merged.push(j);
      }
      if (merged.length) {
        merged.forEach(j => {
          const rr = j + 2;
          q.getRange(rr, Q.SENDER + 1).setValue(sender.name); q.getRange(rr, Q.STATUS + 1).setValue(ST.SENDING);
          q.getRange(rr, Q.TRIES + 1).setValue(Number(v[j][Q.TRIES] || 0) + 1); q.getRange(rr, Q.SENT + 1).setValue(now);
          q.getRange(rr, Q.NOTE + 1).setValue(MERGE_NOTE + r[Q.ID]);
        });
        CacheService.getScriptCache().put('MERGE_' + r[Q.ID], JSON.stringify(merged.map(j => v[j][Q.ID])), 21600);
      }
    }
    return { ok: true, message: { id: r[Q.ID], type: r[Q.TYPE], target: String(r[Q.TARGET]), text, file } };
  }
  if (lim.blocked) { limitNote_(lim, now); if (lim.blocked !== 'target') PropertiesService.getScriptProperties().setProperty('LIMIT_ACTIVE_AT', String(now.getTime())); }
  return { ok: true, message: null, limited: lim.blocked || undefined };
}

/* ========== التاب: تبليغ النتيجة ========== */

// body: {action:'report', device, id, ok:true/false, error:'...'}
function report_(b) {
  const sender = touchSender_(b.device);
  if (!sender) return { ok: false, error: 'جهاز غير معروف' };
  const q = SpreadsheetApp.getActive().getSheetByName(SH.QUEUE);
  const ids = q.getRange(2, 1, Math.max(q.getLastRow() - 1, 1), 1).getValues();
  for (let i = 0; i < ids.length; i++) {
    if (ids[i][0] !== b.id) continue;
    const row = i + 2;
    // الرسائل اللي اندمجت ويا هاي تاخذ نفس النتيجة
    const mj = CacheService.getScriptCache().get('MERGE_' + b.id);
    if (mj) {
      const set = {}; JSON.parse(mj).forEach(id => set[id] = 1);
      for (let k = 0; k < ids.length; k++) if (set[ids[k][0]]) {
        const rr = k + 2;
        if (b.ok) { q.getRange(rr, Q.STATUS + 1).setValue(ST.SENT); q.getRange(rr, Q.SENT + 1).setValue(new Date()); }
        else { const t = Number(q.getRange(rr, Q.TRIES + 1).getValue() || 0); q.getRange(rr, Q.STATUS + 1).setValue(t >= MAX_TRIES ? ST.FAILED : ST.PENDING); q.getRange(rr, Q.NOTE + 1).setValue(String(b.error || 'خطأ غير معروف')); }
      }
      if (!b.ok) CacheService.getScriptCache().remove('MERGE_' + b.id);
    }
    if (b.ok) {
      q.getRange(row, Q.STATUS + 1).setValue(ST.SENT);
      q.getRange(row, Q.SENT + 1).setValue(new Date());
      q.getRange(row, Q.NOTE + 1).setValue('');
    } else {
      const tries = Number(q.getRange(row, Q.TRIES + 1).getValue() || 0);
      q.getRange(row, Q.STATUS + 1).setValue(tries >= MAX_TRIES ? ST.FAILED : ST.PENDING);
      q.getRange(row, Q.NOTE + 1).setValue(String(b.error || 'خطأ غير معروف'));
    }
    return { ok: true };
  }
  return { ok: false, error: 'المعرف مو موجود' };
}

