/* ========== حدود الأمان للإرسال ==========
 * حتى ما ينحظر رقم المركز: حد بالساعة، حد باليوم (من 12 بالليل بتوقيت بغداد)، وحد لكل كروب/رقم بالساعة.
 * الرسالة اللي تعبر الحد ما تنحذف — تبقى «بالانتظار» وتطلع لما ينفتح مجال (مثلاً الساعة الجاية).
 * رسائل «الحارس» (تنبيهات الإدارة لحيدر) ما عليها حد. القيم تتغير من خصائص السكربت: LIMIT_HOUR / LIMIT_DAY / LIMIT_TARGET_HOUR.
 */
const LIMIT_DEFAULT = { HOUR: 40, DAY: 400, TARGET_HOUR: 4 };
const LIMIT_FREE_PROJECTS = ['الحارس'];
const MERGE_MAX = 8, MERGE_CHARS = 3800, MERGE_SEP = '\n\n━━━━━━━━━━━━\n\n', MERGE_NOTE = 'مدموجة ويا ';

function limits_() {
  const p = PropertiesService.getScriptProperties();
  const num = (k, d) => { const x = Number(p.getProperty(k)); return x > 0 ? x : d; };
  return { hour: num('LIMIT_HOUR', LIMIT_DEFAULT.HOUR), day: num('LIMIT_DAY', LIMIT_DEFAULT.DAY), target: num('LIMIT_TARGET_HOUR', LIMIT_DEFAULT.TARGET_HOUR) };
}

function limitsState_(v, now) {
  const L = limits_(), hourAgo = now.getTime() - 3600e3;
  const bg = new Date(now.getTime() + 3 * 3600e3); bg.setUTCHours(0, 0, 0, 0);
  const dayStart = bg.getTime() - 3 * 3600e3;
  let hour = 0, day = 0; const perTarget = {};
  v.forEach(r => {
    if (r[Q.STATUS] !== ST.SENT && r[Q.STATUS] !== ST.SENDING) return;
    if (LIMIT_FREE_PROJECTS.indexOf(String(r[Q.PROJECT]).trim()) > -1 || r[Q.TYPE] === 'فحص') return;
    if (String(r[Q.NOTE]).indexOf(MERGE_NOTE) === 0) return;   // اندمجت ويا رسالة ثانية (انحسبت وحدة)
    const t = new Date(r[Q.SENT] || r[Q.TIME]).getTime(); if (!t) return;
    if (t >= dayStart) day++;
    if (t >= hourAgo) { hour++; const k = String(r[Q.TARGET]); perTarget[k] = (perTarget[k] || 0) + 1; }
  });
  return { L, hour, day, perTarget, blocked: '' };
}

function limitAllows_(lim, r) {
  if (LIMIT_FREE_PROJECTS.indexOf(String(r[Q.PROJECT]).trim()) > -1 || r[Q.TYPE] === 'فحص') return true;
  if (lim.day >= lim.L.day) { lim.blocked = 'day'; return false; }
  if (lim.hour >= lim.L.hour) { lim.blocked = lim.blocked || 'hour'; return false; }
  if ((lim.perTarget[String(r[Q.TARGET])] || 0) >= lim.L.target) { lim.blocked = lim.blocked || 'target'; return false; }
  return true;
}

// يبلّغ حيدر (عن طريق الحارس) مرة وحدة باليوم إذا وصل الحد اليومي، ومرة كل 3 ساعات إذا وصل حد الساعة
function limitNote_(lim, now) {
  if (lim.blocked === 'target') return;
  const p = PropertiesService.getScriptProperties(), key = 'LIMIT_NOTE_' + lim.blocked;
  const last = Number(p.getProperty(key) || 0), gap = lim.blocked === 'day' ? 12 * 3600e3 : 3 * 3600e3;
  if (now.getTime() - last < gap) return;
  p.setProperty(key, String(now.getTime()));
  const txt = lim.blocked === 'day'
    ? `وصل الحد اليومي (${lim.L.day} رسالة). الرسائل الباقية تنتظر وتطلع باجر بعد 12 بالليل — ما ينحذف شي.`
    : `وصل حد الساعة (${lim.L.hour} رسالة بالساعة). الباقي ينتظر ويطلع تدريجياً — ما ينحذف شي.`;
  try { wdSheet_(SH_ERR, HEAD_ERR).appendRow([now, 'مركز الواتساب', 'حدود الأمان', txt, '']); } catch (e) { console.warn(e); }
}
